source .venv/bin/activate && sed -i 's/torch_dtype=torch.bfloat16/dtype=torch.bfloat16/' src/run_inference.py && python - << 'EOF'
import pandas as pd, json
df=pd.read_json('results/pilot/Qwen2.5-0.5B-Instruct.jsonl',lines=True)
print(df.groupby(['task','condition'])[['correct','has_marker','truncated','n_out_tokens']].mean().round(2).to_string())
gold={json.loads(l)['id']:json.loads(l)['gold'] for l in open('datasets/processed/tasks.jsonl')}
for t in df.task.unique():
    for c in ['direct','cot']:
        r=df[(df.task==t)&(df.condition==c)].iloc[3]
        print(f"\n##### {t} / {c} | gold={str(gold[r.id])[:60]} | ans={r.answer!r} | correct={r.correct}\n{r.output[-350:]}")
EOF

